WITH report(kind,a,b,c,d) AS (SELECT 'schema', type, name, tbl_name, coalesce(sql,'') FROM sqlite_schema WHERE name IN ('t0','t1','t2','v0','sqlite_stat1') OR (type='index' AND tbl_name='t2') UNION ALL SELECT 't2-data', quote(c0), quote(c1), quote(c2), '' FROM t2 UNION ALL SELECT 'v0-data', quote(c0), '', '', '' FROM v0 UNION ALL SELECT 'stat', tbl, coalesce(idx,''), stat, '' FROM sqlite_stat1) SELECT kind,a,b,c,d FROM report ORDER BY kind,a,b,c,d;